"""B26 sheet definitions: name -> (sprite count, description). Prompts are generated from these so alternatives can be re-run (suffix @2 -> _v2)."""
PRE = ("Pixel-art game VFX in the chunky crisp pixel style of the reference image (visible pixels, hard edges, limited palette, no smooth airbrush gradients, no painterly blur). "
       "PURE BLACK background (#000000) everywhere, no ground plane, no character, no text, no frame, no border, no watermark. Original design. Additive-blend friendly: glows are bright shapes on black. "
       "Theme: CRIMSON ASCENDANT, a brawler heat-pressure power in deep CRIMSON RED and dark red with orange highlights, white-hot edge lines and small embers. Palette strictly: dark red, crimson, orange, white-hot highlight, no blue, no gold, no yellow-green. ")
FOX = "an original spectral CRIMSON NINE-TAILED FOX (kitsune-like energy beast, NOT a dragon, NOT a serpent, NOT copied from any existing artwork): pointed ears, narrow muzzle, dark-red core with crimson body and orange-white edge highlights, dynamic mane, large forepaws with claws"
def S(n, d): return (n, d)
SHEETS = {
 'concept': S(1, f"ONE single large sprite: {FOX}, the whole beast in a crouched heroic pose seen from the side facing RIGHT, head up, ears back, mouth slightly open, nine clearly readable tails fanning behind it, translucent spectral look. Concept sheet for a fighter-wrapping aura."),
 'head_side': S(4, f"Each is ONLY the HEAD and short neck with mane of {FOX} (no body, no legs, no tails, no paws) in profile facing RIGHT with the neck and mane trailing left. Four variants: mouth closed calm, mouth half open snarling, mouth wide open roaring with fangs, lunging bite with a bright heat-breath at the mouth."),
 'head_front': S(4, f"Each is ONLY the HEAD and short neck with mane of {FOX} (no body, no tails) seen from the FRONT, facing the viewer, symmetrical. Four variants: mouth closed calm, snarling showing fangs, roaring wide open, glaring eyes narrowed with ears flattened."),
 'head_back': S(4, f"Each is ONLY the BACK of the head and neck mane of {FOX} (no body, no tails) seen from BEHIND: two pointed ears, thick mane, nape, no face visible. Four variants of the same, mane swaying differently."),
 'body': S(4, f"Each is a segment of the spectral body of {FOX}, no head and no tails: variants 1) shoulder and chest mane arching, 2) long torso with spine mane, 3) haunch and hind leg, 4) a curled crouched torso. Translucent flame-fur look, drawn to wrap around a standing person."),
 'paw_a': S(4, f"Each is the large FORE-PAW and forearm of {FOX} striking to the RIGHT, claws extended, fur flames trailing left. Four variants in sequence: raised back, swinging, full-extension claw swipe with slash trail, recoil."),
 'paw_b': S(4, f"Each is the large FORE-PAW and forearm of {FOX} slamming DOWNWARD, claws splayed, seen slightly from above. Four variants: raised, descending, impact with splayed claws, pressed into ground with cracks."),
 'tails_rest': S(4, f"Each is a fan of exactly NINE long flame-fur tails of {FOX} seen from the side, all rooted at one point on the RIGHT and spreading LEFT and up in a graceful fan, each tail a clearly separate readable curved silhouette with a bright tip. Four loop frames of a slow breathing sway."),
 'tails_stream': S(4, f"Each is a fan of exactly NINE long flame-fur tails of {FOX}, rooted at the RIGHT and streaming straight back to the LEFT as if running fast, thin and long, nine readable separate silhouettes with bright tips. Four loop frames with the tails flexing."),
 'tails_flare': S(4, f"Each is NINE tails of {FOX} snapped forward then fanning wide open in a dramatic burst, rooted at the bottom centre, spreading radially upward like a crimson peacock fan, nine clear separate tails. Four frames: gathered, snapping inward, opening, fully fanned."),
 'tails_only': S(4, "Each is ONLY a fan of exactly NINE long crimson flame-fur tails of a spectral nine-tailed fox, with NO fox body, NO head, NO legs: just the nine tails rooted together at a single point at the RIGHT and spreading LEFT and up in a graceful fan, each tail a clearly separate readable curved silhouette with a bright white-hot tip. Four loop frames of a slow breathing sway."),
 'tails_only_stream': S(4, "Each is ONLY a fan of exactly NINE long thin crimson flame-fur tails of a spectral nine-tailed fox, NO body, NO head: rooted together at one point at the RIGHT and streaming straight back to the LEFT as in fast running, nine separate readable silhouettes with bright tips. Four loop frames with the tails flexing."),
 'paw_only': S(4, "Each is ONLY a large crimson flame-fur forearm and PAW of a spectral fox striking to the RIGHT, NO head, NO body: forearm entering from the left edge fading into embers, paw with long white claws extended. Four sequence frames: raised back, swinging, full-extension swipe with a slash trail, recoil."),
 'activation': S(4, f"Each is the materialisation of {FOX} around a standing figure: a crimson pressure burst of rising embers, a spectral fox silhouette half formed inside a bright shockwave. Four frames in sequence: embers gathering, silhouette forming, roar burst, settle."),
 'dissolve': S(4, f"Each is {FOX} dissolving into drifting crimson embers and sparks, the shape breaking up from the tails towards the head. Four frames in sequence from mostly solid to almost only embers."),
 'ground_ring': S(4, "Each is a flat GROUND PRESSURE RING seen in perspective as a wide squashed ellipse (3:1): a thin bright crimson ring with a radial fracture line pattern and small embers, expanding. Four frames, ring growing bigger and thinner."),
 'cyclone_arc': S(4, "Each is a sweeping crimson HEAT-BAND ARC: a thick curved crescent slash of spinning flame wind, tapered at both ends, with white-hot inner line and trailing sparks. Four variants: small arc, medium arc, big full circle arc, outward burst arc."),
 'cyclone_crack': S(4, "Each is a FLOOR CRACK STAR seen from above in perspective: a star-shaped burst of glowing crimson fissures radiating from a centre, with white-hot cracks and embers. Four frames growing: small cracks, spreading, full star, fading with embers."),
 'rampage_dust': S(4, "Each is a low burst of DUST and rubble kicked up by a heavy charge: crimson-lit dust clouds with flying stones and orange sparks, horizontal spread. Four frames in sequence."),
 'rampage_trail': S(4, "Each is a horizontal MOMENTUM TRAIL streaking to the LEFT: thin hard speed-lines and a crimson heat smear with embers, pointed at the right end. Four variants of varying length."),
 'giant_fist_l': S(4, "Each is a giant SPECTRAL FIST (a left fist, clenched, knuckles toward the viewer-down) of crimson flame-energy, seen from above-behind, slamming DOWN, with a muscled forearm fading to embers at the top. Four frames: raised high, descending, impact, withdrawing."),
 'giant_fist_r': S(4, "Each is a giant SPECTRAL FIST (a right fist, clenched) of crimson flame-energy, seen from above-behind, slamming DOWN, forearm fading to embers at the top. Four frames: raised high, descending, impact, withdrawing. Clearly a different hand from the left fist (thumb on the other side). Keep a wide black margin around every sprite, nothing touching the sheet edge, forearm fading out into embers well inside the frame."),
 'cat_debris': S(4, "Each is a burst of flying ROCK DEBRIS and glowing crimson shards with embers, from a heavy ground impact, spreading outward. Four frames in sequence."),
 'cat_shock': S(4, "Each is a ground SHOCKWAVE seen in perspective as a squashed ellipse (3:1): a heavy thick crimson ring with white-hot rim, dust and cracks inside, expanding. Four frames."),
 'nova_orb': S(4, "Each is a compact turbulent RED SPHERE of energy sized to fit around a closed fist, with bright rotating spiral rings circling it and embers. Four stages growing: small, medium, large, overcharged with white-hot core."),
 'nova_spiral': S(4, "Each is an expanding RED SPIRAL: a double-arm crimson spiral swirl seen from the front, white-hot lines, embers, increasing in size across four frames."),
 'nova_core': S(4, "Each is a heavy CRIMSON ERUPTION explosion: a bright white-hot core with crimson fireball, radial rays and embers. Four frames in sequence: ignition, full eruption, spreading, dissipating."),
 'nova_ring': S(4, "Each is a thin delayed PRESSURE RING, a perfect circle seen straight-on with crimson distortion bands and sparks, expanding. Four frames growing thinner."),
 'fist_trail': S(4, "Each is a punch TRAIL streaking to the LEFT behind a fast fist: a thick crimson comet streak with a white-hot core, a spiral ripple and embers. Four variants of increasing length."),
 'flight_ring': S(4, "Each is a PAW-SHAPED PRESSURE RING: a ring of crimson shockwave containing a faint fox paw print (one large pad and four toe pads), seen in perspective as a squashed ellipse, expanding. Four frames."),
 'flight_fan': S(4, "Each is a streaming FAN of nine thin crimson comet-tail streaks, rooted at the RIGHT and fanning out to the LEFT behind a flying figure, with embers. Four loop frames."),
 'wisps': S(4, "Each is a small body-bound flame WISP: a short curling lick of crimson flame, about the size of a person forearm, tapered, flickering, with a white-hot core and few embers. Four animation frames of the same wisp, rising."),
 'wisp_arc': S(4, "Each is a tiny thin crimson ENERGY ARC wrapping like a ribbon around a forearm: a curved thin bright band with a few sparks. Four animation frames."),
 'icons': S(6, "Each is a square GAME SKILL ICON with a rounded dark-red tile background, bold clear symbol, high contrast crimson/orange/white; six icons in two rows of three: 1) four-fist combo (a fist with motion lines), 2) spinning cyclone vortex, 3) a charging shoulder/grabbing fist with a slam, 4) two giant fists crossing down, 5) a fist inside a red sphere with spiral, 6) a fox head silhouette with nine tails (Overdrive)."),
}
def prompt(name):
    n, d = SHEETS[name]
    lay = "Sheet with exactly ONE sprite, centred." if n == 1 else ("Sheet with exactly SIX separate sprites in a grid, evenly spaced, separated by wide black gaps." if n == 6 else "Sheet with exactly FOUR separate sprites in one row, evenly spaced, separated by wide black gaps (no sprite touching another or the sheet edge).")
    return PRE + lay + " " + d
